"""Build the public documentation entry point from this source commit (INF-06, BLD-11)."""
import argparse
from datetime import datetime, timezone
import html
import json
import os
from pathlib import Path
import subprocess

ROOT=Path(__file__).resolve().parents[1]
parser=argparse.ArgumentParser();parser.add_argument('--out',type=Path,default=ROOT/'site/_build');args=parser.parse_args()
sha=os.environ.get('GITHUB_SHA') or subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()
repo='https://github.com/crucis-lab/crucis'
source=repo+'/blob/'+sha+'/'
def a(path,label):return '<a href="'+html.escape(source+path)+'">'+html.escape(label)+'</a>'
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Crucis · Causal Discovery Auditing</title><meta name="description" content="An independent framework for controlled audits of causal-discovery systems and their claims.">
<style>
:root{color-scheme:light;--ink:#172c32;--muted:#516268;--paper:#f5f3eb;--line:#d5dacf;--accent:#a9472f}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.65 system-ui,sans-serif}a{color:inherit;text-underline-offset:4px}a:hover{color:var(--accent)}header,main,footer{max-width:1120px;margin:auto;padding:25px 32px}header{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line)}nav{display:flex;flex-wrap:wrap;gap:20px;font-size:14px}.wordmark{font-weight:750;letter-spacing:.12em;text-decoration:none}.hero{padding:64px 0 44px;max-width:900px}.eyebrow{text-transform:uppercase;font-size:12px;letter-spacing:.2em;color:var(--accent);font-weight:700}h1{font:normal clamp(64px,11vw,124px)/1 Georgia,serif;letter-spacing:-.055em;margin:20px 0}h2{font:normal 34px/1.2 Georgia,serif;margin:12px 0 20px}h3{font-size:18px}p{max-width:76ch}.lead{font-size:clamp(22px,3vw,30px);line-height:1.4;max-width:760px}.muted{color:var(--muted)}.pill{display:inline-block;border:1px solid var(--line);border-radius:30px;padding:5px 12px;font-size:12px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.card{padding:24px;background:white;border:1px solid var(--line);border-radius:6px}.card p{font-size:15px}section{padding:34px 0;border-top:1px solid var(--line)}pre{padding:24px;background:var(--ink);color:#ecf1e8;overflow:auto;border-radius:6px;font-size:14px}details{padding:17px 0;border-bottom:1px solid var(--line)}summary{cursor:pointer;font-weight:650}footer{font-size:13px;color:var(--muted);border-top:1px solid var(--line)}:focus-visible{outline:3px solid var(--accent);outline-offset:4px}@media(max-width:740px){header,main,footer{padding-left:20px;padding-right:20px}.grid{grid-template-columns:1fr}.hero{padding-top:35px}header{flex-direction:column}nav{gap:14px}}
</style></head><body><header><a class="wordmark" href="#">CRUCIS</a><nav aria-label="Main"><a href="#start">Get started</a><a href="#protocol">Protocol &amp; scope</a><a href="#benchmark">Benchmark</a><a href="https://uzairgheewala.github.io/cc-research/">Research</a></nav></header><main>
<div class="hero"><span class="eyebrow">Causal discovery auditing</span><h1>Crucis</h1><p class="lead">Preserve the evidence.<br>Put causal claims to the test.</p><p>An independent, system-agnostic framework for controlled audits of causal-discovery systems and their claims. Native evidence, uncertainty and reproducible comparisons belong together.</p><span class="pill">Development version · Apache-2.0</span> <a href="https://github.com/crucis-lab/crucis">Explore the source →</a></div>
<div class="grid"><article class="card"><span class="eyebrow">Connect</span><h3>Keep native meaning</h3><p>Describe what a system accepts and produces. Preserve graphs, orders, probabilities, claims, artifacts and gaps without inventing a common answer.</p></article><article class="card"><span class="eyebrow">Compare</span><h3>Control the experiment</h3><p>Make cases, information, conditions, attempts and independent repetitions explicit. Compare only what the design actually supports.</p></article><article class="card"><span class="eyebrow">Account</span><h3>Make findings inspectable</h3><p>Link measurements and reports to their evidence. Keep unknown effects and inconclusive results visible, and validate the auditor itself.</p></article></div>
<section id="start"><span class="eyebrow">From source</span><h2>Get started</h2><p>The distribution is <code>crucis-causal</code>, the import is <code>crucis_causal</code>, and the command is <code>crucis-causal</code>. No package-index release has been published.</p><pre>git clone https://github.com/crucis-lab/crucis.git
cd crucis
python -m pip install .
python -m crucis_causal --help
python -m crucis_causal systems</pre><p>Installation does not run a paid experiment. Recorded research inputs use an explicit <code>CRUCIS_DATA_ROOT</code>. A registered adapter is a declaration to inspect; it is not evidence of complete native support.</p><p>README_LINK · CITATION_LINK · NOTICE_LINK</p></section>
<section id="protocol"><span class="eyebrow">What exists, what is next</span><h2>Protocol and scope</h2><details open><summary>Connection and experiment foundations</summary><p>System-connection contracts and experiment definitions are implemented with scoped conformance tests. Current support and limitations are recorded in versioned implementation notes.</p><p>S1_LINK · S2_LINK</p></details><details open><summary>Execution and measurement</summary><p>The execution layer implements admission, collection and recovery for declared driver and evidence profiles. Measurement procedures bind their results to explicit inputs, references and execution evidence. The release notes describe the supported profiles and their tests. The findings layer is in development.</p><p>S3_LINK · S4_LINK · PROTOCOL_LINK</p></details><details><summary>What does a passing check establish?</summary><p>A schema or software test validates its declared contract. Scientific correctness, faithful native execution, blinded access and universal system coverage require their own evidence. Test reports retain skipped checks and missing prerequisites.</p></details></section>
<section id="benchmark"><span class="eyebrow">Versioned evaluation</span><h2>A benchmark in development</h2><p>The evaluation suite is being built alongside the framework: controlled cases, appropriate references, compatible information regimes, preserved output semantics and validation of the auditor's own findings. There is no released cross-system leaderboard here.</p><p>The Q1 research study and existing empirical findings live in <a href="https://github.com/uzairgheewala/cc-research">cc-research</a>. The <a href="https://github.com/uzairgheewala/causal-copilot-q1">companion refinement reproduction</a> is a separate, bounded study.</p><p><a href="https://github.com/crucis-lab/crucis/issues/new/choose">Propose an adapter, protocol or benchmark extension →</a></p></section></main><footer>Crucis · Copyright 2026 Uzair Gheewala · Apache-2.0<br>Built from SOURCE_LINK. This deployment's <a href="deployment.json">source receipt</a> identifies the published commit.</footer></body></html>'''
links={'README_LINK':a('README.md','Installation and development'),'CITATION_LINK':a('CITATION.cff','Cite the software'),'NOTICE_LINK':a('THIRD_PARTY_NOTICES.md','Attribution'),
 'S1_LINK':a('crucis_causal/docs/subsystem1-implemented-support-2026-11-01.md','Connection support'),
 'S2_LINK':a('crucis_causal/docs/subsystem2-implemented-scope-2026-11-02.md','Experiment support'),
 'S3_LINK':a('crucis_causal/docs/subsystem3-implemented-scope-2026-11-04.md','Execution support'),
 'S4_LINK':a('crucis_causal/docs/s4/release-review-2026-11-05.md','Measurement release review'),
 'PROTOCOL_LINK':a('crucis_causal/PROTOCOL.md','Historical scientific protocol'),
 'SOURCE_LINK':'<a href="'+repo+'/tree/'+sha+'"><code>'+sha[:12]+'</code></a>'}
for key,value in links.items():page=page.replace(key,value)
args.out.mkdir(parents=True,exist_ok=True)
(args.out/'index.html').write_text(page,encoding='utf-8')
(args.out/'deployment.json').write_text(json.dumps({'source_commit':sha,'repository':repo,'built_utc':datetime.now(timezone.utc).isoformat(),'workflow_run':os.environ.get('GITHUB_RUN_ID')},indent=2)+'\n')
assert all((ROOT/path).is_file() for path in ('README.md','CITATION.cff','THIRD_PARTY_NOTICES.md','crucis_causal/PROTOCOL.md'))
print(json.dumps({'site':str(args.out),'source_commit':sha,'pages':1}))
